(18092, '8.0.1 [ARD] Player - IGC', '--Conditional to account for male/female anim differences\nif genderFemale then\n	playerAnimKit = 16632\n	else playerAnimKit = 16613\nend\n\n-----------------------------------------------------------------------------------------\n\n	WaitForTrigger(\"SetupLoaded\") \n	\n	Actor.Player:IGC_MoveToPathStart( Data.Player.pathData[010] )\n	Actor.Player:IGC_FacingPath(Data.Player.pathData[010], 1, 2)\n	Actor.Player:EquipWeapon(WeaponSlot.MainHand, 11684)\n	\n-- SHOT 010 -----------------------------------------------------------------------------------------\n\n	WaitForTrigger(\"StartShot010\")\n	\n-- SHOT 030 -----------------------------------------------------------------------------------------\n\n	WaitForTrigger(\"StartShot030\")\n	\n	Actor.Player:IGC_FollowPath(Data.Player.pathData[010], 9.65)\n	Actor.Player:SetSheatheState(SheatheState.ShowWeapon, true)\n	Actor.Player:PlayAnimKit(16656, true, -1)\n\n-- SHOT 040 -----------------------------------------------------------------------------------------\n\n	WaitForTrigger(\"StartShot040\")\n	Actor.Player:WaitMovementComplete()\n	Wait(3.3)\n	Actor.Player:StopAnimKit(16656)\n	Actor.Player:PlayAnimKit(playerAnimKit,true,-1)\n	Wait(ShotLength[040]-2.8)\n	Actor.Player:Fade(0,.4)\n\n', 39653),
(18093, '8.0.1 [ARD] Moira - IGC', '	WaitForTrigger(\"SetupLoaded\") \n	\n	Actor.Moira:IGC_MoveToPathStart( Data.Moira.pathData[010] )\n	Actor.Moira:IGC_FacingPath(Data.Moira.pathData[010], 1, 2)\n	Actor.Moira:SetSheatheState(SheatheState.Sheathed, true)\n	Actor.Moira:SetSnapToGround(true)	\n	\n-- SHOT 010 -----------------------------------------------------------------------------------------\n\n	WaitForTrigger(\"StartShot010\")\n	\n	Actor.Moira:IGC_PlayAnim ( Animations.Stand, 0, 0.75, true, 0, 1000) \n	Actor.Moira:SetFacingToTarget(Actor.Player, IGC_ZERO_VECTOR)\n	\n	\n	-- SHOT 040 -----------------------------------------------------------------------------------------\n\n	WaitForTrigger(\"StartShot040\")\n\n	Wait(ShotLength[040]+.4)\n	Actor.Moira:Fade(0,.4)\n\n', 39653),
