INSERT INTO `mount` (`Name`, `SourceText`, `Description`, `ID`, `MountTypeID`, `Flags`, `SourceTypeEnum`, `SourceSpellID`, `PlayerConditionID`, `MountFlyRideHeight`, `UiModelSceneID`, `MountSpecialRiderAnimKitID`, `MountSpecialSpellVisualKitID`, `VerifiedBuild`) VALUES
('Hand of Hrestimorak', '|cFFFFD200Achievement:|r Glory of the Dominant Raider|n|cFFFFD200Zone:|r Sanctum of Domination', 'The treachery of Hrestimorak was infamous, betraying his people to claim power. Facing damnation in the Maw, he tried to subvert the Jailer... a foolish act that would earn him an eternity of torment.', 1417, 230, 0, 0, 339957, 0, 0, 43, 0, 0, 39653),
('Sapphire Skyblazer', '|cFFFFD200Promotion|r |n', 'These brilliant blue birds burn brighter (and hotter) than their orange cousins, though the origin of both remains a mystery.', 1456, 248, 0, 7, 347812, 0, 0, 227, 0, 0, 39653),
('Mawsworn Charger', '|cFFFFD200Achievement:|r Flawless Master|n|cFFFFD200Zone:|r Torghast, Tower of the Damned', 'The fate of all horse mounts.', 1416, 230, 0, -1, 339956, 0, 0, 4, 0, 0, 39653),
('Sanctum Gloomcharger', '|cFFFFD200Drop:|r The Nine|n|cFFFFD200Zone:|r Sanctum of Domination', 'Only the Jailer\'s most powerful lieutenants are gifted these steeds to stalk the halls of the Tower.', 1500, 230, 0, -1, 354351, 0, 0, 4, 0, 0, 39653),
('Soulbound Gloomcharger', '|cFFFFD200Drop:|r Mysterious Gift from Ve\'nari|n|cFFFFD200Zone:|r The Maw', 'Ven\'ari has many methods of sneaking around the Maw and disrupting the Jailer\'s plans, including binding his own minions.', 1501, 230, 0, -1, 354352, 0, 0, 4, 0, 0, 39653),
('Fallen Charger', '|cFFFFD200Drop:|r Fallen Charger|n|cFFFFD200Zone:|r The Maw', 'The charger\'s screams echo across the Maw as it continues a never-ending ride across the land, forever looking for escape from the endless torments it has been forced to endure.', 1502, 230, 0, -1, 354353, 0, 0, 4, 0, 0, 39653);
INSERT INTO `lfg_dungeons` (`ID`, `Name`, `Description`, `TypeID`, `Subtype`, `Faction`, `IconTextureFileID`, `RewardsBgTextureFileID`, `PopupBgTextureFileID`, `ExpansionLevel`, `MapID`, `DifficultyID`, `MinGear`, `GroupID`, `OrderIndex`, `RequiredPlayerConditionId`, `RandomID`, `ScenarioID`, `FinalEncounterID`, `CountTank`, `CountHealer`, `CountDamage`, `MinCountTank`, `MinCountHealer`, `MinCountDamage`, `BonusReputationAmount`, `MentorItemLevel`, `MentorCharLevel`, `ContentTuningID`, `Flags1`, `Flags2`, `VerifiedBuild`) VALUES
(2221, 'The Jailer\'s Vanguard', 'The Jailer\'s vanguard stands ready to repel any attack. Their lines must be broken to breach the Jailer\'s sanctum.', 1, 2, -1, 4181530, 4200804, 4200803, 8, 2450, 17, 195, 0, 18, 90400, 0, 0, 2439, 2, 5, 18, 1, 4, 13, 0, 0, 0, 2107, 16411, 0, 39653),
(2222, 'The Dark Bastille', 'Screams of the tormented fuel the Jailer\'s army. End their suffering and deprive the Maw of its most precious resource.', 1, 2, -1, 4181530, 4200805, 4200803, 8, 2450, 17, 195, 0, 19, 90401, 0, 0, 2443, 2, 5, 18, 1, 4, 13, 0, 0, 0, 2107, 16411, 0, 39653),
(2224, 'The Reckoning', 'Atop the Tower, Sylvanas Windrunner awaits. Here, the final confrontation for the fate of the cosmos will take place.', 1, 2, -1, 4181530, 4200807, 4200803, 8, 2450, 17, 195, 0, 21, 90403, 0, 0, 2441, 2, 5, 18, 1, 4, 13, 0, 0, 0, 2107, 16411, 0, 39653),
(2223, 'Shackles of Fate', 'The soul river ends at the tower\'s peak. Destroy those feeding off it to free the countless souls deprived of their afterlife.', 1, 2, -1, 4181530, 4200806, 4200803, 8, 2450, 17, 195, 0, 20, 90402, 0, 0, 2440, 2, 5, 18, 1, 4, 13, 0, 0, 0, 2107, 16411, 0, 39653),
