INSERT INTO `scene_script_global_text` (`ID`, `Name`, `Script`, `VerifiedBuild`) VALUES
(30853, '9.1 Korthia - Ch 5 - Vashj Entrance (ZTO)', '----------\n-- INIT --\n----------\n\n-- Creature IDs\nnathrezimCreatureID = 178648\nvashjCreatureID = 177167\n\n\n-- Spell Visual IDs\nnathrezimTransformID = 107606\nquestbangID = 107605\narrowSpellID = 352666\n\n--Create Spawns\nvashjFake = SpawnSimulatedNPCActorAtPoint( vashjCreatureID, 39035, true )\nlocal questBang = vashjFake:PlaySpellStateVisual( questbangID )\nnathrezim = SpawnSimulatedNPCActorAtPoint( nathrezimCreatureID, 39035, true )\nnathrezim:Fade( 0, 0 )\nvashjReal = SpawnSimulatedNPCActorAtPoint( vashjCreatureID, 39036, true )\nvashjReal:Fade( 0, 0 )\n\n------------\n-- Action --\n------------\n\nvashjFake:BroadcastTextStereo( BroadcastType.Say, 209784 )\nPlayOneShotSplitBodyAnim( vashjFake, Animations.EmotePoint )\nWait( 3 )\nPlayOneShotSplitBodyAnim( vashjFake, Animations.EmoteTalk )\nWait( 1 )\nvashjFake:WaitBroadcastSoundComplete()\n\nCreateAreaTriggerActor( vashjFake, 15, \"ACTION\" )\n\nWaitForTrigger( \"ACTION\" )\nvashjReal:Fade( 1, 1 )\n--vashjReal:CastSpell( arrowSpellID, vashjFake )\nvashjReal:PlaySpellCastVisualAtTargets( 109738, 1, true, { vashjFake } )\nWait(1)\nvashjFake:PlaySpellImpactVisual( 109738 )\nWait(.5)\nvashjFake:Fade( 0, 0 )\nnathrezim:Fade( 1, 0 )\nnathrezim:PlaySpellCastVisual( nathrezimTransformID )\nnathrezim:PlayLoopingAnimKit( 1034 )\nWait(1)\nvashjFake:Despawn()\nvashjReal:FollowPathAtSpeed( 39038, 7 )\nvashjReal:BroadcastTextStereo( BroadcastType.Say, 209785 )\nscene:TriggerServerEvent( \"AURA\" )\nPlayOneShotSplitBodyAnim( vashjReal, Animations.EmoteTalk )\nvashjReal:WaitMovementComplete()\nWait(1)\nscene:EndScene()', 39653),
